import '../../resources/models/resource_item.dart';

/// How a Nova reply was actually produced. Shown to the user so an offline
/// fallback is never mistaken for generative AI.
enum NovaResponseMode {
  /// A message typed by the user.
  user,

  /// Fixed, deterministic reply (greetings, thanks, unavailable telemetry).
  deterministic,

  /// Generated by the Gemini model (directly or through the proxy).
  gemini,

  /// Built-in reference notes shown because the user asked a factual
  /// question and the online model was not used.
  offlineKnowledge,

  /// Simplified built-in reply used because online generation was
  /// unavailable (see [AiChatMessage.fallbackReason]).
  offlineFallback,

  /// Deterministic safety protocol (never produced by the model).
  safetyProtocol,
}

/// Internal safety outcome attached to a message.
enum SafetyStatus {
  none,

  /// Indirect/ambiguous distress: Nova asks a direct, caring question.
  ambiguous,

  /// Explicit thoughts of self-harm or suicide.
  high,

  /// Stated intent, plan, or means close at hand.
  imminent,
}

/// A source backing a knowledge chunk (title/publisher/URL/date/limits).
class KnowledgeSource {
  final String title;
  final String publisher;
  final String? url;
  final String? published; // year or date as published
  final String? limitation;

  const KnowledgeSource({
    required this.title,
    required this.publisher,
    this.url,
    this.published,
    this.limitation,
  });
}

class AiChatMessage {
  final String id;

  /// The conversational answer (or the user's text).
  final String text;
  final bool isUser;
  final DateTime timestamp;
  final List<String> suggestedChips;

  /// Optional app resource, handled separately from the answer text.
  final ResourceItem? recommendedResource;

  /// Which pipeline path produced this message.
  final NovaResponseMode responseMode;

  /// Reference notes that were retrieved for this reply (may be empty).
  final List<KnowledgeSource> sourceReferences;

  final SafetyStatus safetyStatus;

  /// Human-readable reason when [responseMode] is offlineFallback.
  final String? fallbackReason;

  const AiChatMessage({
    required this.id,
    required this.text,
    required this.isUser,
    required this.timestamp,
    this.suggestedChips = const [],
    this.recommendedResource,
    this.responseMode = NovaResponseMode.deterministic,
    this.sourceReferences = const [],
    this.safetyStatus = SafetyStatus.none,
    this.fallbackReason,
  });

  Map<String, dynamic> toFirestore(String userId) {
    return {
      'id': id,
      'userId': userId,
      'text': text,
      'isUser': isUser,
      'timestamp': timestamp.toIso8601String(),
      'suggestedChips': suggestedChips,
      'recommendedResourceId': recommendedResource?.id,
      'responseMode': responseMode.name,
      'safetyStatus': safetyStatus.name,
      'fallbackReason': fallbackReason,
    };
  }

  factory AiChatMessage.fromFirestore(Map<String, dynamic> data) {
    ResourceItem? resource;
    final resId = data['recommendedResourceId'] as String?;
    if (resId != null && resId.isNotEmpty) {
      try {
        resource = ResourceItem.catalog.firstWhere((r) => r.id == resId);
      } catch (_) {}
    }

    final modeName = data['responseMode'] as String? ?? 'deterministic';
    final mode = NovaResponseMode.values.firstWhere(
      (m) => m.name == modeName,
      orElse: () => NovaResponseMode.deterministic,
    );

    final safetyName = data['safetyStatus'] as String? ?? 'none';
    final safety = SafetyStatus.values.firstWhere(
      (s) => s.name == safetyName,
      orElse: () => SafetyStatus.none,
    );

    DateTime ts = DateTime.now();
    final rawTs = data['timestamp'];
    if (rawTs is String) {
      ts = DateTime.tryParse(rawTs) ?? DateTime.now();
    }

    final chips = (data['suggestedChips'] as List<dynamic>?)
            ?.map((e) => e.toString())
            .toList() ??
        const [];

    return AiChatMessage(
      id: data['id'] as String? ?? '',
      text: data['text'] as String? ?? '',
      isUser: data['isUser'] as bool? ?? false,
      timestamp: ts,
      suggestedChips: chips,
      recommendedResource: resource,
      responseMode: mode,
      safetyStatus: safety,
      fallbackReason: data['fallbackReason'] as String?,
    );
  }
}
